import {icon} from './icons.js';
import {num,selectStops} from './data.js';
import {metricHelp} from './metric-help.js';
import {AIR_BENCHMARKS,AIR_SOURCES,aqiTone} from './air-data.js';
import {planOnNetwork,ROUTING_SOURCE} from './routing.js';
import {dataNotice} from './provenance.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

export function statCard(title,value,unit,ico,footer,warn=false,helpKey='',reference=''){
  const keys={'Контейнеров в квартале':'containers','Требуют внимания':'attention','Средняя заполненность':'fill','Качество воздуха':'euAqi'};
  const references={containers:'Охват: все площадки квартала',attention:'Пороги пилота: 75% / 90%',fill:'Порог вывоза площадки: 75%',euAqi:'Ориентир: 0–20 · хорошо'};
  const help=helpKey||keys[title]||'';
  return `<div class="stat-card ${warn?'warn':''}"><div class="stat-top"><span>${title}</span><span class="stat-head-icons">${metricHelp(help)}<span class="stat-icon">${icon(ico)}</span></span></div><div class="stat-value">${value}<small>${unit}</small></div><div class="stat-bottom"><span>${footer}</span></div>${reference||references[help]?`<div class="metric-reference">${reference||references[help]}</div>`:''}</div>`;
}
export function forecastChart(air,mini=false){
  const data=air?.chart??[];if(!data.length)return '<div class="empty-chart">Прогноз появится после загрузки источника</div>';
  const w=mini?280:850,h=mini?85:255,left=mini?0:38,right=mini?0:22,top=mini?8:22,bottom=mini?8:32;
  const max=Math.max(40,Math.ceil(Math.max(...data.map(p=>p.value))/20)*20),pw=w-left-right,ph=h-top-bottom;
  const y=v=>top+ph-v/max*ph,coords=data.map((p,i)=>[left+i/(data.length-1||1)*pw,y(p.value)]),line=coords.map((p,i)=>`${i?'L':'M'}${p[0].toFixed(1)},${p[1].toFixed(1)}`).join(' ');
  return `<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img" aria-label="Прогноз европейского AQI на 24 часа; линия 20 обозначает верхнюю границу хорошей категории"><defs><linearGradient id="forecast-blue-${mini}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#4186ff" stop-opacity=".2"/><stop offset="1" stop-color="#4186ff" stop-opacity=".01"/></linearGradient></defs>${[0,20,max].filter((v,i,a)=>a.indexOf(v)===i).map(v=>`<path d="M${left} ${y(v)}H${w-right}" stroke="${v===20?'#90b3ef':'#e9eef6'}" stroke-dasharray="${v===20?'5 5':'3 5'}"/>${!mini?`<text x="${left-10}" y="${y(v)+4}" text-anchor="end" fill="#95a1b4" font-size="10">${v}</text>`:''}`).join('')}<path d="${line}L${w-right},${h-bottom}H${left}Z" fill="url(#forecast-blue-${mini})"/><path d="${line}" fill="none" stroke="#397cf4" stroke-width="${mini?2:2.5}" stroke-linejoin="round"/>${!mini?coords.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="4" class="forecast-point" tabindex="0" role="img" aria-label="${esc(data[i].time.slice(11,16))}: ${num(data[i].value)} AQI"><title>${esc(data[i].time.slice(11,16))} · ${num(data[i].value)} AQI</title></circle>`).join(''):''}${!mini?[0,6,12,18,23].filter(i=>data[i]).map(i=>`<text x="${coords[i][0]}" y="${h-7}" text-anchor="middle" fill="#95a1b4" font-size="10">${esc(data[i].time.slice(11,16))}</text>`).join(''):''}</svg>`;
}
export function airSummary(state){
  const current=state.air?.current,tone=aqiTone(current?.european_aqi);
  return `<section class="panel air-panel air-summary"><div class="panel-head"><h2 class="panel-title">${icon('wind')}Воздух в Астане</h2><a href="#air" class="icon-button" aria-label="Разобрать показатели воздуха">${icon('arrow-up-right')}</a></div><div class="air-number-line"><div class="air-number" style="color:${tone.color}">${num(current?.european_aqi)}<small>Европейский AQI ${metricHelp('euAqi')}</small></div><span class="air-state" style="color:${tone.color};background:${tone.background}">${current?tone.label:state.airLoading?'Загрузка…':'Нет данных'}</span></div><div class="summary-reference">Ориентир: <strong>0–20</strong> · хорошее качество</div><div class="air-metrics"><div><span>PM2.5 ${metricHelp('pm2_5')}</span><strong>${num(current?.pm2_5,1)} <small>мкг/м³</small></strong><small class="reference-small">Хороший диапазон EEA: 0–5</small></div><div><span>PM10 ${metricHelp('pm10')}</span><strong>${num(current?.pm10,1)} <small>мкг/м³</small></strong><small class="reference-small">Хороший диапазон EEA: 0–15</small></div></div><div class="air-chart-wrap"><div class="air-chart">${forecastChart(state.air,true)}</div><div class="chart-labels"><span>Модельный прогноз · 24 часа</span><span>${metricHelp('forecast')}</span></div></div><div class="air-source">${icon('database')}<span>${state.airError?'Источник временно недоступен':`Open-Meteo · CAMS${current?' · '+esc(current.time.slice(11,16)):''}`}</span><a href="#air" class="text-button" style="margin-left:auto">Подробнее ${icon('arrow-right')}</a></div></section>`;
}
function airMetric(title,value,unit,key,reference,sub){
  return `<article class="panel air-metric-card"><div class="air-metric-head"><span>${title}</span>${metricHelp(key)}</div><div class="air-metric-value">${num(value,1)}<small>${unit}</small></div><p>${sub}</p><div class="air-reference-pill">${icon('locate')}<span>${reference}</span></div></article>`;
}
function dayCard(state,key,label){
  const reading=state.air?.rolling?.[key],value=reading?.average,reference=AIR_BENCHMARKS[key].daily,known=Number.isFinite(value),ratio=known?value/reference:null;
  return `<div class="day-metric"><div class="day-metric-label">${label} · среднее за 24 ч ${metricHelp('pmDay')}</div><div class="day-value">${num(value,1)}<small>мкг/м³</small>${known?`<span class="day-status ${ratio>1?'above':''}">${ratio>1?'Выше ориентира':'Ниже ориентира'}</span>`:''}</div><div class="day-track"><span style="width:${known?Math.min(100,ratio*100):0}%;background:${ratio>1?'#cf9751':'#3479f1'}"></span></div><div class="day-reference"><span>Ориентир ВОЗ: <strong>${reference} мкг/м³</strong></span><span>${known?'24 из 24 часов':`${reading?.count??0} из 24 часов`}</span></div>${!known?'<p class="day-missing">Нужно 24 последовательных значения без пропусков.</p>':''}</div>`;
}
export function airView({state,heading}){
  const c=state.air?.current,tone=aqiTone(c?.european_aqi),usTone=aqiTone(c?.us_aqi,'us');
  return heading('Понимать воздух. Видеть контекст.','Каждое число — с объяснением, периодом расчёта и ориентиром.','AIR QUALITY / АСТАНА',false)+
  `<section class="air-hero air-hero-dark"><div class="air-hero-content"><span class="hero-kicker">${icon('pin')}${esc(state.settings.city)}</span><h2>${c?tone.label:state.airLoading?'Получаем данные…':'Источник пока недоступен'}</h2><p>Атмосферная модель CAMS · ${c?esc(c.time.replace('T',' ')):'Open-Meteo'}<br>${esc(state.air?.timezone??'Координаты пилота')} · модельное значение, не датчик во дворе</p><div class="hero-reference"><span class="hero-reference-dot" style="background:${tone.color}"></span>Ориентир европейской шкалы: <strong>0–20 · хорошо</strong></div></div><div class="hero-aqi"><div class="hero-aqi-ring"><strong>${num(c?.european_aqi)}</strong><span>Европейский AQI ${metricHelp('euAqi')}</span></div></div></section>`+
  (state.airError?`<div class="error-note">${icon('info')} ${esc(state.airError)} <button class="text-button" data-action="refresh-air">Повторить загрузку</button></div>`:'')+
  `<div class="metric-grid air-metric-grid">${airMetric('Мелкие частицы PM2.5',c?.pm2_5,'мкг/м³','pm2_5','EEA · хорошо: 0–5 мкг/м³','Текущая часовая оценка модели')}${airMetric('Частицы PM10',c?.pm10,'мкг/м³','pm10','EEA · хорошо: 0–15 мкг/м³','Текущая часовая оценка модели')}${airMetric('Европейский AQI',c?.european_aqi,'AQI','euAqi','Хорошая категория: 0–20',tone.label)}${airMetric('Американский AQI',c?.us_aqi,'AQI','usAqi','Хорошая категория: 0–50',usTone.label)}</div>`+
  `<section class="panel day-panel"><div class="day-panel-heading"><div><span class="section-kicker">СРАВНИВАЕМ ОДИНАКОВЫЕ ПЕРИОДЫ</span><h2>Суточные ориентиры ВОЗ ${metricHelp('pmDay')}</h2><p>Среднее последних 24 модельных часов. Будущие прогнозные часы сюда не входят.</p></div><a href="${AIR_SOURCES.whoTable}" class="button" target="_blank" rel="noopener">Таблица ВОЗ ${icon('external')}</a></div><div class="day-grid">${dayCard(state,'pm2_5','PM2.5')}${dayCard(state,'pm10','PM10')}</div><div class="day-note">${icon('info')}Это ориентировочное сопоставление модели с рекомендациями ВОЗ. Оно не заменяет данные датчика или официальную оценку нормативов.</div></section>`+
  `<section class="panel content-panel forecast-panel"><div class="section-heading"><div><h2>Что ожидает модель ${metricHelp('forecast')}</h2><p>Европейский AQI · следующие 24 часа · ${esc(state.air?.timezone??'часовой пояс источника')}</p></div><button class="button" data-action="refresh-air" ${state.airLoading?'disabled':''}>${icon('refresh',state.airLoading?'spin':'')}Обновить</button></div><div class="forecast-legend"><span><i></i>Прогноз CAMS</span><span><i class="dashed"></i>Граница «хорошо» · AQI 20</span></div><div class="large-chart">${forecastChart(state.air)}</div></section>`+
  `<section class="air-reading-guide"><div><span class="guide-index">01</span><h3>Наведите на «i»</h3><p>Что значит показатель, как он рассчитан, какие числа служат ориентиром. На телефоне — нажмите.</p></div><div><span class="guide-index">02</span><h3>Смотрите на период</h3><p>Часовой показатель сравнивают с часовой шкалой. Суточный ориентир — со средним за 24 часа.</p></div><div><span class="guide-index">03</span><h3>Учитывайте источник</h3><p>Это внешняя атмосферная модель. Собственных датчиков и подтверждённого эффекта EcoMind на воздух пока нет.</p></div></section>`+
  `<div class="page-grid" style="margin-top:20px"><section class="panel content-panel"><h2>Точка наблюдения</h2><p>Получите модельные данные для нужных координат.</p><form id="air-coordinates" style="margin-top:20px"><div class="form-grid"><div class="field"><label for="air-lat">Широта</label><input id="air-lat" name="latitude" type="number" min="-90" max="90" step="any" value="${state.settings.latitude}" required></div><div class="field"><label for="air-lng">Долгота</label><input id="air-lng" name="longitude" type="number" min="-180" max="180" step="any" value="${state.settings.longitude}" required></div></div><button class="button primary" type="submit">${icon('locate')}Получить данные</button></form></section><section class="panel content-panel air-sources-panel"><h2>Проверяемые источники</h2><p>Ориентиры подписаны: европейская шкала EEA, американская шкала EPA и рекомендации ВОЗ используют разные правила.</p><div class="source-link-list"><a href="${AIR_SOURCES.model}" target="_blank" rel="noopener">Open-Meteo / CAMS ${icon('external')}</a><a href="${AIR_SOURCES.eea}" target="_blank" rel="noopener">Европейская шкала EEA ${icon('external')}</a><a href="${AIR_SOURCES.us}" target="_blank" rel="noopener">EPA / AirNow ${icon('external')}</a><a href="${AIR_SOURCES.who}" target="_blank" rel="noopener">Рекомендации ВОЗ ${icon('external')}</a></div></section></div>`;
}

export function roadStatus(state){
  const phase=state.roads.status;
  if(phase==='error')return `<div class="road-status failed">${icon('warning')}<span><strong>Маршрут по дорогам не построен</strong><small>${esc(state.roads.error)}</small></span><button class="button" data-action="calculate-route">Повторить</button></div>`;
  if(phase==='ready')return `<div class="road-status ready">${icon('route')}<span><strong>${state.roads.plan?.points.length>2?'Маршрут построен по дорогам Астаны':'Нет остановок по выбранным условиям'}</strong><small>${state.roads.plan?.points.length>2?ROUTING_SOURCE:'Уменьшите порог или выберите календарный вывоз.'}</small></span><span class="badge">Автомобильный профиль</span></div>`;
  return `<div class="road-status">${icon('refresh','spin')}<span><strong>Строим маршрут по дорожной сети</strong><small>Проверяем проезды и привязываем точки остановки к дороге.</small></span></div>`;
}
export function routesView({state,heading,mapPanel,currentRoute}){
  const route=currentRoute(),selected=selectStops(state.containers,state.route.policy,state.route.threshold,state.route.horizon),stops=route?route.points.slice(1,-1):selected;
  const duration=route?route.duration/60+stops.length*state.settings.stopMinutes:null;
  return heading('По дорогам. До каждой остановки.','Сравнивайте автомобильные маршруты по одному набору площадок.','ROUTE PLANNER / АСТАНА',false)+dataNotice(state.containers,'routes')+roadStatus(state)+
  `<div class="route-layout"><div class="panel route-controls"><h3>Параметры рейса</h3><div class="field"><label for="route-policy">Какие контейнеры вывозить</label><select id="route-policy"><option value="current" ${state.route.policy==='current'?'selected':''}>По текущей заполненности</option><option value="calendar" ${state.route.policy==='calendar'?'selected':''}>Все, по календарю</option><option value="forecast" ${state.route.policy==='forecast'?'selected':''}>По сценарию заполнения</option></select></div><div class="field"><label for="route-threshold">Порог вывоза <strong id="threshold-value">${state.route.threshold}%</strong> ${metricHelp('threshold')}</label><input type="range" id="route-threshold" min="40" max="95" step="5" value="${state.route.threshold}" ${state.route.policy==='calendar'?'disabled':''}><small>Рабочий ориентир пилота: 75%. Срочный приоритет — 90%.</small></div>${state.route.policy==='forecast'?`<div class="field"><label for="route-horizon">Горизонт сценария</label><select id="route-horizon">${[12,24,48].map(value=>`<option value="${value}" ${state.route.horizon===value?'selected':''}>Через ${value} часов</option>`).join('')}</select><small>Линейный демонстрационный рост, без обученной модели.</small></div>`:''}<button class="button primary wide" data-action="calculate-route" ${state.roads.status==='loading'?'disabled':''}>${icon('route')}Пересчитать маршрут</button><div class="route-help">Порядок выбирается по автомобильным расстояниям. Условные координаты привязываются к проезду в пределах 400 м. Линия отображается только после ответа дорожного сервиса.</div><div class="section-heading"><h3 style="margin:0;font-size:12px">${route?'Порядок остановок':'Выбрано площадок'}</h3><span class="badge">${stops.length}</span></div><div class="route-stop-list">${stops.map((c,i)=>{const snap=route?.snaps?.find(s=>s.id===c.id);return `<button class="route-stop" data-container="${c.id}" style="width:100%;text-align:left"><span>${i+1}</span><span>${esc(c.name)}<small>${esc(c.id)}${snap?` · подъезд ${num(snap.offset)} м от точки`:''}</small></span><span class="badge ${c.fill>=90?'red':'orange'}">${c.fill}%</span></button>`;}).join('')||'<p class="route-help">Нет контейнеров выше порога.</p>'}</div><div class="route-downloads"><button class="text-button" data-action="export-route" ${!route?'disabled':''}>${icon('download')}План CSV</button><button class="text-button" data-action="export-route-geojson" ${!route?.geometry?'disabled':''}>${icon('download')}Маршрут GeoJSON</button></div></div><div>${mapPanel(true,'route')}<div class="route-summary"><div class="panel"><div class="summary-title">Длина по дорогам ${metricHelp('distance')}</div><strong>${num(route?.distance,2)} <small>км</small></strong><small>По геометрии OSRM</small></div><div class="panel"><div class="summary-title">Время рейса ${metricHelp('duration')}</div><strong>${num(duration)} <small>мин</small></strong><small>Движение + ${state.settings.stopMinutes} мин на остановку</small></div><div class="panel"><div class="summary-title">Изменение длины ${metricHelp('saving')}</div><strong>${num(route?.saving,1)}<small>%</small></strong><small>Те же остановки, другой порядок</small></div></div></div></div><div class="methodology"><strong>Как читать расчёт.</strong> Длина и время движения получены из автомобильного маршрута OSRM по дорогам OpenStreetMap. Остановки показываются на ближайшем проезде, без прямых отрезков к условным координатам внутри квартала. Текущие пробки, габариты и масса мусоровоза не учитываются; доступность площадки требует проверки подрядчиком. <a href="https://routing.openstreetmap.de/about.html" target="_blank" rel="noopener">Источник маршрутизации</a> · <a href="https://www.openstreetmap.org/fixthemap" target="_blank" rel="noopener">Исправить карту</a></div>`;
}

export function analyticsView({state,heading}){
  const network=state.roads.network;
  const rows=[['calendar','По календарю'],['current','По текущей оценке'],['forecast','По сценарию +24 ч']].map(([policy,label])=>{
    const stops=selectStops(state.containers,policy,state.route.threshold,24);let plan;
    try{if(network)plan=planOnNetwork(network,stops);}catch{}
    return `<tr><td>${label}<small>${policy==='calendar'?'Все площадки реестра':policy==='forecast'?'Демонстрационный рост заполнения':'Выбор по текущему порогу'}</small></td><td>${stops.length}</td><td>${num(plan?.originalDistance,2)} км</td><td><strong>${num(plan?.distance,2)} км</strong></td><td>${plan?`<span class="badge">−${num(plan.saving,1)}%</span>`:'—'}</td></tr>`;
  }).join('');
  const phase=state.roads.networkStatus;
  return heading('Польза, которую можно проверить.','Отделяем эффект выбора площадок от эффекта порядка остановок.','АНАЛИТИКА / МАТРИЦА 3 × 2',false)+dataNotice(state.containers,'routes')+`<section class="panel content-panel"><div class="section-heading"><div><h2>Одинаковые остановки. Два порядка. ${metricHelp('saving')}</h2><p>Автомобильные расстояния OSRM · порог отбора ${state.route.threshold}%.</p></div><button class="button" data-action="export-simulation" ${!network?'disabled':''}>${icon('download')}Скачать</button></div>${phase==='error'?`<div class="error-note">${esc(state.roads.networkError)} <button class="text-button" data-action="retry-network">Повторить</button></div>`:!network?'<div class="road-status">'+icon('refresh','spin')+'<span>Получаем матрицу дорожных расстояний…</span></div>':''}<div class="table-wrap"><table class="simulation-table"><thead><tr><th>Правило выбора</th><th>Остановки</th><th>Базовый порядок</th><th>Новый порядок</th><th>Разница ${metricHelp('saving')}</th></tr></thead><tbody>${rows}</tbody></table></div><div class="analytics-footnote">${icon('info')}Здесь используются суммы направленных дорожных расстояний между остановками. На странице маршрута длина уточняется по полной геометрии рейса. Расчёты не являются полевыми результатами.</div></section><div class="page-grid" style="margin-top:20px"><section class="panel content-panel"><span class="connected-icon">${icon('route')}</span><h2 style="margin-top:17px">Как сравнивать</h2><p>В одной строке набор остановок одинаков: разница показывает вклад их порядка. Между строками меняется выбор площадок. Сокращение пробега нельзя оценивать без переполнений и уровня обслуживания.</p></section><section class="panel content-panel"><span class="connected-icon">${icon('database')}</span><h2 style="margin-top:17px">Что будет эталоном пилота</h2><p>Фактический рейс подрядчика: GPS-трек, время движения и остановок, обязательные вывозы, переполнения и путевые листы. Пока этих данных нет, эталон — только базовый порядок на том же дорожном графе.</p></section></div><section class="panel content-panel" style="margin-top:20px"><h2>От демонстрации к реальному кварталу</h2><div class="page-grid" style="margin-top:20px">${[['01','Подтвердить площадки','Координаты, вместимость, подъезды и обязательный график.'],['02','Собрать историю','Фото до и после вывоза, фактические остановки, GPS и жалобы.'],['03','Проверить расчёты','Сопоставить дорожный маршрут и время с реальными рейсами.'],['04','Сравнить в полях','Сопоставимые дни и одинаковый уровень обслуживания.']].map(([n,t,d])=>`<div class="pilot-step"><span>${n}</span><div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}</div></section>`;
}
